SELECT 
FROM ai_operation_proposal
WHERE user_id = #{userId}

    AND status = #{status}

ORDER BY id DESC
LIMIT #{limit}

SELECT 
FROM ai_operation_proposal
WHERE conversation_id = #{conversationId}
  AND target_type = #{targetType}
  AND action = #{action}
  AND status = 'PENDING'
  AND expires_at > NOW()


        AND target_id = #{targetId}


        AND target_id IS NULL


ORDER BY id DESC
LIMIT 5

